WoWFA_Data[382888] = "پس از زدن Critical Strike با یک اسپل یا توانایی، برای 3 ضربهٔ نزدیک بعدی‌تان سرعت حمله را 15% افزایش می‌دهد."
WoWFA_Data[383010] = "تعداد Elemental Shieldهایی که می‌توانید روی خودتان فعال داشته باشید 1 عدد افزایش می‌یابد.\n\nمی‌توانید هم‌زمان Earth Shield را روی خودتان و یک متحد داشته باشید."
WoWFA_Data[383013] = "توتمی در پایتان احضار می‌کند که برای 6 ثانیه، هر 1.5 ثانیه تمام اثرات Poison را از یک عضو پارتی یا رید نزدیک در فاصلهٔ 30 یاردی حذف می‌کند."
WoWFA_Data[383016] = "‏Purify Spirit علاوه بر آن، تمام اثرات Curse را حذف می‌کند."
WoWFA_En[383222] = "$?a455630[Surging Totem][Healing Rain] instantly restores $383223s1 health to $s3 allies within its area, and its radius is increased by $s1 $Lyard:yards;."
WoWFA_Data[383222] = "$?a455630[‏Surging Totem][‏Healing Rain] بلافاصله به 5 متحد در محدودهٔ خود $383223s1 سلامتی برمی‌گرداند و شعاعش 2 یارد افزایش می‌یابد."
WoWFA_Data[384143] = "‏Maelstrom Weapon اکنون 5 بار اضافی استک می‌شود.\n\nهر استک Maelstrom Weapon مصرف‌شده یک Overflowing Maelstrom می‌دهد که زمان کست کست بعدی Healing Surge یا Chain Heal شما را 10% کاهش می‌دهد و شفای آن‌ها را 10% افزایش می‌دهد؛ تا 10 بار. این اثر می‌تواند تا 20 بار انباشته شود."
WoWFA_Data[384149] = "‏Lightning Bolt و Chain Lightning می‌توانند تا 10 استک Maelstrom Weapon مصرف کنند."
WoWFA_En[384352] = "Unleash a devastating storm around yourself, dealing $469270s1 Stormstrike damage every $466772s5 sec to nearby enemies for $466772d.\n\nIncreases your chance to activate Windfury Weapon by $466772s1%, and the damage of Windfury Weapon by $466772s2%.\n"
WoWFA_Data[384352] = "طوفانی ویرانگر دور خود آزاد می‌کنید که برای 8 ثانیه، هر 1 ثانیه به دشمنان نزدیک $469270s1 آسیب Stormstrike وارد می‌کند.\n\nشانس فعال شدن Windfury Weapon شما را 50% و آسیب Windfury Weapon را 20% افزایش می‌دهد."
WoWFA_Data[384355] = "هر امبوی فعال سلاح، تمام آسیب Fire، Frost و Nature واردشده را 5% افزایش می‌دهد."
WoWFA_Data[384363] = "هر هدفی که Crash Lightning اصابت می‌کند، آسیب کست بعدی Stormstrike شما را 25% افزایش می‌دهد؛ تا سقف 6 استک."
WoWFA_Data[384411] = "در طول Doom Winds یا Ascendance، هر 1 ثانیه 1 استک Maelstrom Weapon تولید می‌کنید."
WoWFA_Data[384444] = "‏Doom Winds و Deeply Rooted Elements 2 ثانیه بیشتر دوام می‌آورند و کول‌داون Ascendance 60 ثانیه کاهش می‌یابد.\n\nدر طول Doom Winds یا Ascendance، Stormstrike و Crash Lightning تا 10 استک Maelstrom Weapon را مصرف می‌کنند تا با اثربخشی 100% یک Lightning Bolt یا Chain Lightning به سمت دشمن شما تخلیه کنند؛ هر کدام که اخیراً استفاده کرده‌اید."
WoWFA_Data[384450] = "مصرف کردن 10 استک Maelstrom Weapon، آسیب کست بعدی Stormstrike یا Lava Lash شما را 25% افزایش می‌دهد و باعث می‌شود آن‌ها یک استک Maelstrom Weapon تولید کنند."
WoWFA_Data[390288] = "‏Windfury Weapon 100% شانس دارد حملهٔ سومی را فعال کند."
WoWFA_Data[390370] = "وقتی Lava Lash به هدفی تحت تأثیر Flame Shock شما اصابت می‌کند، کول‌داونش 2 ثانیه کاهش می‌یابد."
WoWFA_Data[392352] = "شانس فعال شدن Windfury و Stormsurge توسط Mastery: Enhanced Elements را 150% افزایش می‌دهد."
WoWFA_Data[392915] = "$@spelltooltip5394"
WoWFA_Data[392916] = "$@spelltooltip5394"
WoWFA_En[443418] = "Lava Burst gains an additional charge and deals $s2% increased damage.$?a137039[\n\nRiptide gains an additional charge and heals for $s3% more.][]"
WoWFA_Data[443418] = "‏Lava Burst یک شارژ اضافی می‌گیرد و 10% آسیب بیشتری می‌زند.$?a137039[\n\n‏Riptide یک شارژ اضافی می‌گیرد و 20% بیشتر شفا می‌دهد.][]"
WoWFA_Data[443423] = "‏Ancestorها 20% شانس دارند وقتی می‌روند، برای 8 ثانیه یک Ancestor دیگر فرا بخوانند."
WoWFA_Data[443425] = "استفاده از اسپل‌هایی که زمان کست دارند، مدت Spiritwalker's Grace و Spiritwalker's Aegis را 1 ثانیه افزایش می‌دهد؛ تا سقف 4 ثانیه."
WoWFA_Data[443441] = "‏Earth Shield 3 شارژ اضافی دارد و 25% بیشتر شما را شفا می‌دهد."
WoWFA_Data[443442] = "کول‌داون Nature's Guardian را 15 ثانیه کاهش می‌دهد و باعث می‌شود به‌اندازهٔ 10% اضافی از حداکثر سلامتی شما شفا دهد."
WoWFA_Data[443444] = "‏Ancestorها 4 ثانیه بیشتر دوام می‌آورند."
WoWFA_En[443445] = "$?a137040[Lightning Bolt, Lava Burst, Flame Shock, Voltaic Blaze, and Chain Lightning have a $s2][Riptide has a $s1]% chance to call an Ancestor to your side for $445624d."
WoWFA_Data[443445] = "$?a137040[‏Lightning Bolt، Lava Burst، Flame Shock، Voltaic Blaze و Chain Lightning 8][‏Riptide 15]% شانس دارند برای 8 ثانیه یک Ancestor را به کنار شما فرا بخوانند."
WoWFA_En[443446] = "When an Ancestor departs, they cast $?a137040[Elemental Blast at a nearby enemy.][Hydrobubble on a nearby injured ally.\n\n$@spellicon444490 |cFFFFFFFF$@spellname444490|r\n$@spelldesc444490]"
WoWFA_Data[443446] = "وقتی یک Ancestor می‌رود، $?a137040[به سمت دشمنی نزدیک Elemental Blast کست می‌کند.][روی متحد زخمی نزدیک Hydrobubble کست می‌کند.\n\n |cFFFFFFFFHydrobubble|r\nSurrounds your target in a protective water bubble for 15 ثانیه.\n\nThe shield absorbs the next $?a443449[${$s1*(1+$443449s1/100)}][$s1] incoming damage, but the absorb amount decays fully over its duration.]"
WoWFA_En[443447] = "$?a137040[Increases the damage of Earth Shock, Elemental Blast, and Earthquake by $s1%.\n\nIncreases the healing of Healing Surge and Chain Heal by $s2%.][Increases the healing done by Healing Wave, Downpour, and Chain Heal by $s2%.]"
WoWFA_Data[443447] = "$?a137040[آسیب Earth Shock، Elemental Blast و Earthquake را 25% افزایش می‌دهد.\n\nشفای Healing Surge و Chain Heal را 25% افزایش می‌دهد.][شفای Healing Wave، Downpour و Chain Heal را 25% افزایش می‌دهد.]"
WoWFA_En[443448] = "Increases your maximum $?a137040[Maelstrom by $s1.][mana by $s2%.\n\nTidal Waves can now stack up to ${$s3+$s4} times.]"
WoWFA_Data[443448] = "$?a137040[حداکثر Maelstrom شما را 25 افزایش می‌دهد.][حداکثر Mana شما را 10% افزایش می‌دهد.\n\n‏Tidal Waves اکنون می‌تواند تا 3 بار استک شود.]"
WoWFA_Data[443449] = "اسپل‌های Ancestorهای شما 25% قدرتمندتر است."
WoWFA_En[443450] = "$?a137040[Stormkeeper calls an Ancestor to your side for $445624d.][Unleash Life calls an Ancestor to your side for $s1 sec.]\n\nWhenever you cast a healing or damaging spell, the Ancestor will cast a similar spell."
WoWFA_Data[443450] = "$?a137040[‏Stormkeeper برای 8 ثانیه یک Ancestor را به کنار شما فرا می‌خواند.][‏Unleash Life برای 12 ثانیه یک Ancestor را به کنار شما فرا می‌خواند.]\n\nهر وقت یک اسپل شفابخش یا آسیب‌زننده کست کنید، Ancestor نیز اسپلی مشابه کست می‌کند."
WoWFA_En[443451] = "When an Ancestor is called, they reduce the cooldown of $?a137040[Stormkeeper by ${$s1/-1000} sec.][Riptide by ${$s2/-1000} sec.]"
WoWFA_Data[443451] = "وقتی یک Ancestor فرا خوانده می‌شود، کول‌داون $?a137040[Stormkeeper را 3 ثانیه][Riptide را 2 ثانیه] کاهش می‌دهد."
WoWFA_En[445024] = "Elemental motes orbit around your Surging Totem. Your abilities consume the motes for enhanced effects. \n\n$?a137041[|cFFFFFFFFAir:|r $@spelldesc453409\n\n|cFFFFFFFFEarth:|r $@spelldesc453406\n\n|cFFFFFFFFFire:|r $@spelldesc453405][|cFFFFFFFFWater:|r $@spelldesc453407\n\n|cFFFFFFFFAir:|r $@spelldesc453409\n\n|cFFFFFFFFEarth:|r $@spelldesc453406]"
WoWFA_Data[445024] = "ذرات عنصری دور Surging Totem شما می‌چرخند. توانایی‌های شما ذرات را برای اثرات تقویت‌شده مصرف می‌کنند. \n\n$?a137041[|cFFFFFFFFهوا:|r $?a137041[Your next Lightning Bolt, Chain Lightning or Elemental Blast unleashes 3 Surging Bolts at your Surging Totem.][The cast time of your next healing spell is reduced by 40%.]\n\n|cFFFFFFFFزمین:|r $?a137041[Your next Sundering deals 100% increased damage and summons a Searing Totem.][Your next Chain Heal applies Earthliving at 150% effectiveness to all targets hit.]\n\n|cFFFFFFFFآتش:|r Your next Lava Lash grants you Hot Hand for 8 sec.][|cFFFFFFFFآب:|r Your next Healing Wave also heals an ally inside of your Healing Rain at 50% effectiveness.\n\n|cFFFFFFFFهوا:|r $?a137041[Your next Lightning Bolt, Chain Lightning or Elemental Blast unleashes 3 Surging Bolts at your Surging Totem.][The cast time of your next healing spell is reduced by 40%.]\n\n|cFFFFFFFFزمین:|r $?a137041[Your next Sundering deals 100% increased damage and summons a Searing Totem.][Your next Chain Heal applies Earthliving at 150% effectiveness to all targets hit.]]"
WoWFA_En[445025] = "$?a137041[Lightning Bolt, Chain Lightning and Elemental Blast has a chance to unleash a Surging Bolt at your Surging Totem, increasing the totem's damage by $458269s1%, and then redirecting the bolt to your target for $458267s1 Nature damage. The damage bonus effect can stack.][Chain Heal now jumps to a nearby totem within $458357A3 yards once it reaches its last target, causing the totem to cast Chain Heal on an injured ally within $458357r yards for $458357s1. Jumps to $s1 nearby targets within $458357A3 yards.]"
WoWFA_Data[445025] = "$?a137041[‏Lightning Bolt، Chain Lightning و Elemental Blast شانس دارند یک Surging Bolt به سمت Surging Totem شما آزاد کنند؛ این کار آسیب توتم را 10% افزایش می‌دهد و سپس همان شلیک را به سمت هدف شما هدایت می‌کند و $458267s1 آسیب Nature وارد می‌کند. اثر افزایش آسیب می‌تواند استک شود.][‏Chain Heal اکنون پس از رسیدن به هدف آخرش، به توتمی نزدیک در فاصلهٔ 20 یاردی پرش می‌کند و باعث می‌شود آن توتم روی متحد زخمیِ در فاصلهٔ $458357r یاردی به‌اندازهٔ $458357s1 شفا دهد. به 2 هدف نزدیک در فاصلهٔ 20 یاردی پرش می‌کند.]"
WoWFA_Data[445026] = "اندازه و شعاع توتم‌های شما را 15% و سلامتی توتم‌هایتان را 30% افزایش می‌دهد."
WoWFA_Data[445027] = "حذف موفقیت‌آمیز یک اثر زیان‌بار با Tremor Totem یا Poison Cleansing Totem، یا کنترل کردن دشمنی با Capacitor Totem یا Earthgrab Totem، کول‌داون توتم استفاده‌شده را $/1000;s1 ثانیه کاهش می‌دهد.\n\nبرای هر توتم، بیشتر از هر 20 ثانیه یک‌بار رخ نمی‌دهد."
WoWFA_En[445028] = "$?a137041[Increases the chance for Windfury Weapon to trigger by $s1% and increases its damage by $s2%.\n\nWhen Flametongue Weapon triggers from Windfury Weapon attacks, it has a chance to gather a whirl of flame around the target, dealing $s5% of its damage to all nearby enemies.][Increases the duration of your Earthliving effect by ${$s3/1000} sec.]\n"
WoWFA_Data[445028] = "$?a137041[شانس فعال شدن Windfury Weapon را 5% افزایش می‌دهد و آسیب آن را 8% زیاد می‌کند.\n\nوقتی Flametongue Weapon از حمله‌های Windfury Weapon فعال می‌شود، شانس دارد چرخه‌ای از شعله دور هدف جمع کند که 300% از آسیبش را به تمام دشمنان نزدیک وارد می‌کند.][مدت اثر Earthliving شما را 3 ثانیه افزایش می‌دهد.]"
WoWFA_Data[445029] = "وقتی Surging Totem فعال است، آسیب و شفای شما 3% افزایش می‌یابد."
WoWFA_En[445030] = "Surging Totem $?a462110[heals for $s1% more][deals $s2% more damage] while Ascendance or Healing Tide Totem is active."
WoWFA_Data[445030] = "‏Surging Totem در طول فعال بودن Ascendance یا Healing Tide Totem، $?a462110[150% بیشتر شفا می‌دهد][50% آسیب بیشتری می‌زند]."
WoWFA_En[445031] = "If you have a totem active, your totem grants you a shield absorbing ${$mhp*$s1/100} damage for $457387d every $457390d."
WoWFA_Data[445031] = "اگر توتم فعالی داشته باشید، توتم شما هر 30 ثانیه برای 30 ثانیه سپری به شما می‌دهد که ${$mhp*$s1/100} آسیب جذب می‌کند."
WoWFA_En[445032] = "$?a137041[Increases the damage of Surging Totem by $s1%.][Increases the healing done by Surging Totem by $s2%.]"
WoWFA_Data[445032] = "$?a137041[آسیب Surging Totem را 18% افزایش می‌دهد.][شفای Surging Totem را 10% افزایش می‌دهد.]"
WoWFA_En[445033] = "$?a137041[Increases the critical strike chance of Flametongue Weapon by $s1%, and its critical strike damage by $s2%.][Learn a new weapon imbue, Tidecaller's Guard.\n\n$@spellicon457481 $@spellname457481\n$@spelldesc457481 ]"
WoWFA_Data[445033] = "$?a137041[شانس Critical Strike Flametongue Weapon را 25% و آسیب Critical Strike آن را 100% افزایش می‌دهد.][یک امبوی سلاح جدید یاد می‌گیرید: Tidecaller's Guard.\n\n Tidecaller's Guard\nImbue your shield with the element of Water for 1 ساعت. Your healing done is increased by 2% and the duration of your Healing Stream Totem is increased by 3 sec. ]"
WoWFA_En[445034] = "$?a137041[Lava Lash has a chance to summon a Searing Totem to hurl Searing Bolts that deal $3606s1 Fire damage to a nearby enemy. Lasts $458101d.\n\nLava Lash and Voltaic Blaze cause your Searing Totems to shoot a Searing Volley at up to $s3 nearby enemies for $458147s1 Fire damage.][When you summon a Healing Tide Totem, Healing Stream Totem, or Spirit Link Totem you cast a free instant Chain Heal at $458221s2% effectiveness.]"
WoWFA_Data[445034] = "$?a137041[‏Lava Lash شانس دارد یک Searing Totem احضار کند که Searing Bolt به سمت دشمنی نزدیک پرتاب می‌کند و $3606s1 آسیب Fire وارد می‌کند. مدت 8 ثانیه.\n\n‏Lava Lash و Voltaic Blaze باعث می‌شوند Searing Totemهای شما تا 5 دشمن نزدیک را با یک Searing Volley هدف بگیرند و $458147s1 آسیب Fire وارد کنند.][وقتی Healing Tide Totem، Healing Stream Totem یا Spirit Link Totem احضار می‌کنید، یک Chain Heal فوری و رایگان با اثربخشی 100% کست می‌کنید.]"
WoWFA_En[445035] = "$?a137041[While Hot Hand is active Lava Lash shatters the earth, causing a Sundering at $s1% effectiveness.][Your Healing Stream Totems heals an additional ally at $s3% effectiveness.\n\nHealing Tide Totem healing increased by $s2%.]"
WoWFA_Data[445035] = "$?a137041[وقتی Hot Hand فعال است، Lava Lash زمین را می‌شکافد و یک Sundering با اثربخشی 80% ایجاد می‌کند.][‏Healing Stream Totem شما یک متحد اضافی را با اثربخشی 30% شفا می‌دهد.\n\nشفای Healing Tide Totem 25% افزایش می‌یابد.]"
WoWFA_En[445036] = "$?a137041[Increases the critical strike chance of your Searing Totem's attacks by $s1%, and its critical strike damage by $s2%.][Chain Heals from Lively Totem and Totemic Rebound are $s3% more effective.]"
WoWFA_Data[445036] = "$?a137041[شانس Critical Strike حمله‌های Searing Totem شما را 15% و آسیب Critical Strike آن را 30% افزایش می‌دهد.][‏Chain Healهای حاصل از Lively Totem و Totemic Rebound اثربخشی 25% بیشتری دارند.]"
WoWFA_En[448861] = "$@spelldesc443454"
WoWFA_Data[448861] = "Your next healing or damaging spell$?a1246131[ or Hex][] is instant, costs no mana, and deals 10% increased damage and healing.\n\nIf you know Nature's Swiftness, it is replaced by Ancestral Swiftness and causes Ancestral Swiftness to call an Ancestor to your side for 8 ثانیه."
WoWFA_En[454009] = "$?s137040[Each Maelstrom spent has a ${$s1/100}.2% chance to upgrade][Each Maelstrom Weapon spent has a ${$s2/100}.2% chance to upgrade] your next Lightning Bolt to Tempest.\n\n$@spelltooltip452201"
WoWFA_Data[454009] = "$?s137040[هر Maelstrom مصرف‌شده 0.3% شانس دارد][هر استک Maelstrom Weapon مصرف‌شده 2% شانس دارد] کست بعدی Lightning Bolt شما را به Tempest ارتقا دهد.\n\n$@spelltooltip452201"
WoWFA_Data[454021] = "شانس Critical Strike اسپل‌های آسیب Nature شما را 5% و آسیب Critical Strike اسپل‌های Nature شما را 5% افزایش می‌دهد."
WoWFA_Data[454022] = "‏Tempest سرعت حرکت شما را برای 5 ثانیه به‌اندازهٔ 20% افزایش می‌دهد."
WoWFA_En[454026] = "$?s137040[Reduces the cooldown of Stormkeeper by ${$s1/-1000} sec.][Doom Winds summons a Nature Feral Spirit for ${$s2/1000} sec.\n\n$@spellicon469314$@spellname469314\nAn Elemental Spirit infused with Nature magic, granting the summoner with $224125s1% increased Nature damage and $224125s3% Physical damage for ${$s2/1000} sec.]"
WoWFA_Data[454026] = "$?s137040[کول‌داون Stormkeeper را 15 ثانیه کاهش می‌دهد.][‏Doom Winds برای 12 ثانیه یک Feral Spirit طبیعتی احضار می‌کند.\n\nFeral Spirit\nروحی عنصری آغشته به جادوی Nature که برای 12 ثانیه، 5% آسیب Nature و 5% آسیب Physical بیشتری به احضارکننده می‌دهد.]"
WoWFA_Data[454027] = "‏Lightning Shield آسیب دریافتی شما را 3% کاهش می‌دهد."
WoWFA_Data[454372] = "کست کردن Tempest به شما Surging Currents می‌دهد که اثربخشی کست بعدی Chain Heal یا Healing Surge شما را 16% افزایش می‌دهد؛ تا سقف 80%."
WoWFA_En[454391] = "Spending $?s137040[Maelstrom][Maelstrom Weapon stacks] grants you $454394s1% haste for $454394d.\n\nMultiple applications may overlap."
WoWFA_Data[454391] = "مصرف کردن $?s137040[Maelstrom][استک‌های Maelstrom Weapon] برای 15 ثانیه به شما 1% Haste می‌دهد.\n\nچندین اعمال این اثر می‌توانند هم‌زمان فعال باشند."
WoWFA_En[454919] = "$?s137040[Earthquake][Crash Lightning] and Chain Lightning damage increased by $s1%."
WoWFA_Data[454919] = "آسیب $?s137040[Earthquake][Crash Lightning] و Chain Lightning 15% افزایش می‌یابد."
WoWFA_En[455088] = "Tempest grants ${$455089s1*$mas}% Mastery for $455089d.\n"
WoWFA_Data[455088] = "‏Tempest برای 6 ثانیه مقدار ${$455089s1*$mas}% Mastery به شما می‌دهد."
WoWFA_En[455096] = "$?s137040[Casting Tempest grants a charge of Stormkeeper.][Tempest causes your next Chain Lightning to be instant cast, deal $455097s2% increased damage, and cast an additional time.\n\nCan accumulate up to $470532U charges.]"
WoWFA_Data[455096] = "$?s137040[کست کردن Tempest یک شارژ Stormkeeper به شما می‌دهد.][‏Tempest باعث می‌شود کست بعدی Chain Lightning شما کست فوری شود، 40% آسیب بیشتری بزند و یک بار اضافی کست شود.\n\nتا $470532U شارژ می‌تواند انباشته شود.]"
WoWFA_En[455110] = "$?s137040[Lightning Bolt, Tempest, and Chain Lightning Elemental Overloads deal $s1% additional damage.][Lightning Bolt, Tempest, and Chain Lightning have a $s2% chance to refund $s3 Maelstrom Weapon stacks.]"
WoWFA_Data[455110] = "$?s137040[‏Elemental Overloadهای Lightning Bolt، Tempest و Chain Lightning 10% آسیب اضافی می‌زنند.][‏Lightning Bolt، Tempest و Chain Lightning 35% شانس دارند 2 استک Maelstrom Weapon را برگردانند.]"
WoWFA_En[455123] = "$?s137040[Lightning Rod targets now also take $s2% of the damage that Tempest deals, and Tempest also applies Lightning Rod effect.][Gain the effects of the Lightning Rod talent:\n\n$@spellicon210689 $@spellname210689\n$@spelldesc210689]"
WoWFA_Data[455123] = "$?s137040[هدف‌های Lightning Rod اکنون 10% از آسیبی که Tempest وارد می‌کند را نیز دریافت می‌کنند و Tempest نیز اثر Lightning Rod را اعمال می‌کند.][اثرات تلنت Lightning Rod را به دست می‌آورید:\n\n Lightning Rod\n$?s454009[Tempest، ][]$?s137040[Earth Shock، Elemental Blast و Earthquake][Lightning Bolt و Chain Lightning] هدف شما را برای 8 ثانیه به یک Lightning Rod تبدیل می‌کند.\n \n‏Lightning Rodها 10% از تمام آسیبی که با $?s454009[Tempest، Lightning Bolt،][Lightning Bolt] و Chain Lightning وارد می‌کنید را دریافت می‌کنند.]"
WoWFA_En[455129] = "$?a137040[Each Maelstrom spent has an additional ${$s3/100}.2% chance to upgrade your next Lightning Bolt to Tempest.][Stormstrike has a small chance to upgrade your next Lightning Bolt to Tempest.]"
WoWFA_Data[455129] = "$?a137040[هر Maelstrom مصرف‌شده شانس اضافی 0.3% دارد که کست بعدی Lightning Bolt شما را به Tempest ارتقا دهد.][‏Stormstrike شانس کمی دارد که کست بعدی Lightning Bolt شما را به Tempest ارتقا دهد.]"
WoWFA_En[455590] = "$?a137041[Casting Sundering within $s2 yards of your Surging Totem causes it to create a Tremor at $s1% effectiveness at the target area.][Allies affected by your Earthliving effect receive $s3% increased healing from you.]"
WoWFA_Data[455590] = "$?a137041[کست کردن Sundering در فاصلهٔ 40 یاردی Surging Totem شما باعث می‌شود در مکان هدف، یک Tremor با اثربخشی 125% ایجاد کند.][متحدانی که تحت اثر Earthliving شما هستند 15% شفای بیشتری از شما دریافت می‌کنند.]"
WoWFA_Data[462368] = "شفای Healing Stream Totem، آسیب Fire، Frost و Nature دریافتی را برای 3 ثانیه به‌اندازهٔ 6% کاهش می‌دهد."
WoWFA_En[462383] = "Spirit Link Totem reduces damage taken by an additional $s1%, and it restores $462384s1 health to all nearby allies $m2 $Lsecond:seconds; after it is dropped. Healing reduced beyond $s3 targets.\n"
WoWFA_Data[462383] = "‏Spirit Link Totem آسیب دریافتی را 5% اضافی کاهش می‌دهد و 1 ثانیه پس از گذاشته شدن، به تمام متحدان نزدیک $462384s1 سلامتی برمی‌گرداند. شفای بیش از 5 هدف کاهش می‌یابد."
